"""Explain existing questions with named objects, review criteria and time units."""
from html import escape as e
import hashlib
import json
from pathlib import Path
from site_navigation import project_tabs, experiment_subtabs

ROOT=Path(__file__).resolve().parents[1]
D=ROOT/'research/question-expansion'
def read(name): return json.loads((D/name).read_text())
def p(text): return '<p>'+e(str(text))+'</p>'
def table(number,caption,headers,rows):
    head=''.join('<th scope="col">'+e(h)+'</th>' for h in headers)
    body=''.join('<tr>'+''.join('<td>'+e(str(v))+'</td>' for v in row)+'</tr>' for row in rows)
    label=f'Table {number}. {caption}'
    return f'<div class="qe-table"><p class="qe-table-caption" aria-hidden="true">{e(label)}</p><div class="qe-table-scroll"><table><caption class="qe-sr-only">{e(label)}</caption><thead><tr>{head}</tr></thead><tbody>{body}</tbody></table></div></div>'
def clock(seconds):
    minutes,rest=divmod(seconds,60)
    return f'{int(minutes):02d}:{rest:05.2f}'
def metrics(items):
    return '<dl class="qe-metrics">'+''.join('<div><dt>'+e(label)+'</dt><dd>'+e(str(value))+'</dd></div>' for label,value in items)+'</dl>'

CONDITIONS={'full_prefix':'All discussion before the question','recent_60s':'Only the latest 60 seconds','question_only':'Question without any transcript','speaker_labels_removed':'Earlier discussion without speaker labels','evidence_removed':'Earlier discussion with selected source excerpts removed'}
GRADES={'adequate':'Correct and supported','partial':'Partly correct','incorrect':'Wrong','missing':'Needed information absent','unsupported':'Unsupported conclusion'}
STATUS={'retain':'Retained question','reject':'Excluded example','legacy':'Earlier pilot comparison'}
ORIGINS={'authored':'Written by the report assistant','local':'Written by the local 30B model','legacy':'Earlier pilot wording'}

def question_card(q,explanations,durations):
    explanation=explanations[q['id']]
    time_text=clock(q['at'])+' into '+q['meeting']
    if q['meeting'] in durations:
        time_text+=f" · {q['at']/durations[q['meeting']]['seconds']*100:.1f}% of the conversation"
    time_text+=' · participant '+q['requester']+' asks a separate assistant'
    evidence=''
    for c in q.get('source_evidence',[]):
        evidence+='<li><strong>Participant '+e(c['speaker'])+'</strong> · '+clock(c['start'])+'–'+clock(c['end'])+' · <code>'+e(c['id'])+'</code>'
        evidence+=p(c['text']) if c.get('text') else p('The source text stays in the original ConEC dataset; this ID identifies the cited passage.')
        evidence+='</li>'
    answers=''
    for r in q['readbacks']:
        response=r.get('response') or {}
        answers+='<div class="qe-reader"><h4>'+e(CONDITIONS[r['condition']])+'</h4>'+p(response.get('answer') or 'No complete answer was returned.')
        answers+=p('Transcript passages cited by the reader: '+(', '.join(response.get('evidence_ids',[])) or 'none'))
        if response.get('missing_information'):answers+=p('Information the reader says is missing: '+'; '.join(response['missing_information']))
        if r['invalid_evidence_ids']:answers+=p('Error: these cited passages were not supplied: '+', '.join(r['invalid_evidence_ids']))
        answers+='</div>'
    if q.get('span_readbacks'):
        answers+='<details><summary>Later test requiring a copied source quotation</summary>'
        for r in q['span_readbacks']:
            response=r.get('response') or {}
            answers+=p('All earlier discussion: '+(response.get('answer') or 'The model declined to answer.'))
            answers+=p('The quotation did not match the source exactly.' if r['span_errors'] else 'The model supplied no quotation supporting an answer.')
        answers+='</details>'
    grade=q['reader_review']
    return ('<article class="card qe-question" id="'+e(q['id'])+'" data-status="'+e(q['final_decision'])+'" data-dataset="'+e(q['dataset_group'])+'" data-origin="'+e(q['origin_group'])+'">'
        +'<div class="qe-tags"><span class="tag">'+STATUS[q['final_decision']]+'</span><span class="tag blue">'+ORIGINS[q['origin_group']]+'</span></div><h3>'+e(q['question'])+'</h3>'
        +p(explanation['context'])+'<p class="qe-time">'+e(time_text)+'</p>'+p(explanation['motivation'])
        +'<p><strong>Answer checked against the source:</strong> '+e(q['reviewed_reference'])+'</p>'+p(explanation['review'])
        +p('Reader answer with all earlier discussion: '+GRADES[grade['full_prefix']]+'. With only the latest minute: '+GRADES[grade['recent_60s']]+'.')
        +'<details><summary>Inspect source passages and recorded reader answers</summary><p>Each passage ID identifies a short, timed transcript excerpt. The answers below are the model’s original outputs; errors have not been silently corrected.</p><ul>'+evidence+'</ul>'+answers+'</details></article>')

def main():
    study=read('study.json');questions=read('questions.json');timing=read('timing-statistics.json')
    explanations=read('question-explanations.json');reasoning=read('reasoning-literature.json')
    tools=read('tool-fixtures.json');datasets=read('literature.json');s=timing['cohorts']['wordings']['summary']
    body='<header class="site-nav"><div class="nav-inner"><a class="brand" href="../index.html">AI2AI Duplex</a>'+project_tabs('experiments','../')+'</div></header>'
    body+='<div class="container collection-nav">'+experiment_subtabs('ami')+'</div><main id="main"><div class="container">'
    body+='<header class="hero"><span class="eyebrow">Meeting-question study · 26 October 2026</span><h1>What questions did we create, and when would they be asked?</h1><p class="lede">We kept 23 question wordings covering 15 distinct information needs in six conversations. This version tests recall of earlier discussion. It does not yet establish questions that require multiple reasoning steps.</p></header>'

    body+='<section class="section" id="findings"><h2>What is in the current set?</h2>'+metrics([('Retained wordings',23),('Distinct questions',15),('Conversations',6),('Planned question moments',11)])
    body+='<p>A <strong>wording</strong> is one version of a spoken question. Two versions asking for the same information count as one <strong>distinct question</strong>. Several questions are alternatives at the same point in a conversation; they would not all be inserted together.</p><p>The new material includes one real AMI project meeting, three AMI role-play meetings about designing a TV remote, and two earnings calls. The earnings questions simulate a participant privately asking a separate assistant while listening to the call. They are separate from the recorded analysts’ questions to management.</p>'
    names={'EN2002b':'AMI · meeting-browser project','ES2002b':'AMI · TV-remote design','IS1000b':'AMI · TV-remote design','TS3003b':'AMI · TV-remote design','EC4344338':'Danaher · Q1 2020 earnings','EC4320211':'Monro · Q3 FY2020 earnings'}
    body+=table(1,'The retained set by conversation. Duration is the full conversation length; question times are planned positions in that original recording.',['Conversation','Duration','Distinct questions','Wordings','Planned moments'],[[m['meeting']+' · '+names[m['meeting']],f"{m['duration_minutes']:.1f} min",m['information_needs'],m['wordings'],m['planned_moments']] for m in timing['per_meeting']])
    body+='<p>The local model produced 26 complete question drafts: 10 from the full earlier transcript and 16 after the report assistant selected relevant evidence. The report assistant also wrote 16 drafts. Of these 42 complete drafts, 23 wordings were retained: 15 written by the report assistant and eight by the local model. The nine questions reused from the earlier workshop pilot are comparison examples and are excluded from these totals.</p><p><a href="#questions">Review the questions</a> · <a href="#timing">See their planned times</a> · <a href="#harder-questions">Read the proposal for harder questions</a></p></section>'

    body+='<section class="section" id="quality"><h2>How did we decide whether to keep a question?</h2><p>The report assistant checked each draft against the available transcript. This was a source review by an AI assistant, not an independent human rating. A question was kept only when earlier discussion supported its premise and answer, its requester had a plausible reason to ask, and its wording was suitable for speech.</p>'
    body+='<ul><li><strong>Source support:</strong> required facts must appear before the proposed question time. A guess stays a guess, and a proposed idea stays a proposal.</li><li><strong>Requester and wording:</strong> the question must fit the participant’s current task. Transcript letters such as A or D must not be spoken as if they were names.</li><li><strong>Need for earlier discussion:</strong> the latest minute must not already contain the complete answer, and the question must not reveal its own answer.</li><li><strong>Correct proposed answer:</strong> numbers, responsibilities and changed plans must match the source. A usable question can need a corrected answer label while its wording stays unchanged.</li></ul>'
    body+='<p>Table 2 concerns one specific generation setting: eight AMI question times, with two instructions tried at each time, for <strong>16 requests to Qwen3-30B Instruct</strong>. Each request asked for one question and proposed answer using all earlier speech. This table describes those 16 outputs; it is not a count of the final retained set.</p>'
    body+=table(2,'Outcomes of the 16 initial model-generation requests. The five rows sum to 16. “Model” describes generation behavior; “reviewer” describes the later source check.',['What happened?','Requests','Meaning and review criterion'],[
        ['Model declined to write a question',5,'The model explicitly returned that it had no suitable question. There was no question for the reviewer to accept or reject.'],
        ['Model stopped before completing its question-and-answer output',1,'The output reached its 3,072-token limit while listing supporting transcript passages. It did not finish the requested question-and-answer output.'],
        ['Reviewer rejected the complete question',6,'The question assumed an unstated fact, asked for a new design approval instead of a reminder, confused survey findings with an agreed decision, or used a transcript letter as a name.'],
        ['Question needed its proposed answer corrected',2,'The wording was plausible, but source references or the description of the current plan needed correction before use.'],
        ['Plausible question; another version was preferred',2,'Another wording covered the same information need. These were not counted as failures or added again to the reader test.']])
    body+='<h3>Three concrete errors, with their meeting context</h3><p><strong>An assumed cost limit:</strong> in TS3003b, the team discusses a docking station—a base that can recharge the TV remote. The model asked what the budget limit for that base had been. The available discussion did not assign a separate cost limit to the base, so the question assumed information that had never been stated.</p><p><strong>A transcript letter used as a name:</strong> another draft began “D, can you remind us…”. A–D are labels added to identify AMI speakers. D was also the selected requester, so the wording had that participant address their own transcript label.</p><p><strong>Two survey percentages confused:</strong> in the IS1000b product-design role-play, the marketing participant reports a survey of remote-control users. Fifty percent often lose their remotes; 34% find a new remote hard to learn. In the later generation setting, the report assistant first selected relevant earlier utterances and described the information needed. Even with that help, the model’s proposed answer used 34% for losing the remote. The source-checked answer is 50%.</p></section>'

    body+='<section class="section" id="timing"><h2>When would the retained questions be asked?</h2>'
    body+=f"<p>Across the 23 wordings, the planned question time averages <strong>{s['mean_elapsed_minutes']:.1f} minutes</strong> after the conversation starts, or <strong>{s['mean_percent']:.1f}%</strong> of the full conversation. The earliest is {s['min_elapsed_minutes']:.1f} minutes in; the latest is {s['max_elapsed_minutes']:.1f} minutes in. These are proposed positions in the source recording. This expansion did not insert new audio.</p>"
    body+='<p><strong>The timing is biased by our selection rule.</strong> AMI candidate times were chosen near 56% and 86% of each meeting, then adjusted to pauses. Earnings-call candidates were chosen near 60% and 86% of their timed transcript span. The final percentages use official full conversation durations. No retained question is before 53%; this is not a measured distribution of when real people ask assistants for help.</p>'
    body+='<label class="qe-chart-control">Count in the plots <select id="timing-cohort"><option value="wordings">All 23 retained wordings</option><option value="information_needs">15 distinct questions, one count each</option></select></label><p id="timing-summary" aria-live="polite"></p>'
    body+='<figure id="timing-figure"><div class="qe-plots">'
    for measure,alt in [('percent','Planned question position as a percentage of conversation length, with the mean marked'),('minutes','Minutes elapsed before a planned question, with the mean marked')]:
        stem='../research/question-expansion/figures/wordings-'+measure
        body+='<div><img id="timing-'+measure+'" src="'+stem+'.png" alt="'+alt+'"><p><a id="'+measure+'-svg" href="'+stem+'.svg">SVG</a> · <a id="'+measure+'-pdf" href="'+stem+'.pdf">PDF</a></p></div>'
    body+='</div><figcaption>Figure 1. Planned insertion times for retained questions only. Green bars count AMI questions and gold bars count earnings-call questions. The dashed line marks the mean for the selected counting unit. Percentage bins are 10 points wide; elapsed-time bins are five minutes wide. Alternative wordings share the same original timeline and add no new meeting time.</figcaption></figure>'
    body+=table(3,'Exact timing summaries for both counting units. Averages are over question records, not an equal-weight average of the six conversations.',['Counting unit','Count','Mean elapsed','Median elapsed','Mean position','Median position','Range of positions'],[[label,c['summary']['n'],f"{c['summary']['mean_elapsed_minutes']:.2f} min",f"{c['summary']['median_elapsed_minutes']:.2f} min",f"{c['summary']['mean_percent']:.2f}%",f"{c['summary']['median_percent']:.2f}%",f"{c['summary']['min_percent']:.2f}–{c['summary']['max_percent']:.2f}%"] for label,c in [('All retained wordings',timing['cohorts']['wordings']),('Distinct questions',timing['cohorts']['information_needs'])]])
    body+='<p><a href="../research/question-expansion/timing-statistics.json">Download every question time, conversation duration and histogram bin count</a>. The fraction elapsed is the question time divided by the full conversation duration. It does not measure how far back the answer is located.</p></section>'

    body+='<section class="section" id="pipeline"><h2>How the questions and answers were produced</h2><figure class="qe-flow"><div class="qe-stages">'
    modules=[('1 · Choose an available transcript','Speaker-labelled, timed speech and a proposed question time.','Only speech completed before that time. This earlier part of the conversation is the model’s context.'),('2 · Choose the requester and information need','Earlier speech, the current discussion and formal roles where available.','A participant who has a plausible reason to ask and an earlier fact that would help them.'),('3 · Write a question and proposed answer','Either all earlier speech, or relevant earlier utterances selected by the report assistant. The report assistant also writes comparison drafts.','One spoken question, a proposed answer and source IDs. The selected-evidence setting gives the model no already-written question or answer.'),('4 · Ask the reader model to answer','The question, requester and allowed transcript. The proposed answer and selected source list are hidden.','Qwen3-30B Instruct’s answer, cited passages and any missing facts. The question is tested with five versions of the context.'),('5 · Check against the source','The question, model answers and actual earlier utterances.','A decision about the question and a separately checked answer label. Fluent wording or a valid output format is not enough.')]
    for title,inp,out in modules:body+='<div><h3>'+e(title)+'</h3><dl><dt>Input</dt><dd>'+e(inp)+'</dd><dt>Output</dt><dd>'+e(out)+'</dd></dl></div>'
    body+='</div><figcaption>Figure 2. The existing text-generation and review process. The reader is the model answering a proposed user question. A source ID identifies a short transcript excerpt. No new generation was run for this report revision.</figcaption></figure><p>Source selection happens offline and can inspect complete transcript files. The generation and reader models receive only the chosen earlier speech. This study does not measure prediction of future requests. The local generator and reader use the same Qwen3-30B-A3B-Instruct-2507 checkpoint, so their agreement is not an independent check.</p></section>'

    body+='<section class="section" id="reader"><h2>What did the reader answer correctly?</h2><p>The reader was tested on 32 new question drafts and nine unchanged questions from the earlier EN2003a pilot. Each was answered with five versions of the context: all earlier speech; only the latest minute; no transcript; earlier speech without speaker labels; and earlier speech with selected supporting excerpts removed. That makes 205 model answers.</p>'
    reader_rows=[]
    for label,n,full,recent,kept in study['reader_rows']:
        label={'New assistant-authored':'New drafts written by the report assistant','New local 30B wordings':'New drafts written by the local model','Earlier EN2003a comparison':'Earlier workshop questions'}[label]
        reader_rows.append([label,n,f'{full}/{n}',f'{recent}/{n}','Comparison only' if 'Earlier' in label else f'{kept}/{n}'])
    body+=table(4,'Source review of recorded reader answers. Correct answers preserve the required facts, numbers, speaker and state of the plan, without material unsupported additions. Partly correct answers do not count as correct.',['Question group','Questions tested','Correct: all earlier speech','Correct: latest minute only','Questions retained'],reader_rows)
    body+='<p>Question quality and reader accuracy were checked separately. The remote-loss question is clear and has a source-supported answer of 50%, even though the reader gives 34%. Retaining that question does not mean accepting the reader’s wrong answer.</p><p>A reader’s failure with only the latest minute also does not prove that older history is needed. In EN2002b, the three search-result types were repeated inside that minute, but the reader still failed to list them. We excluded that early version as a history test. The assistant-written version uses a later time when the recent minute does not contain the list.</p><p>All 205 responses were complete machine-readable records, yet 34 cited passages that were not supplied: 33 with no transcript and one after supporting excerpts had been removed. The reader also missed changes to talk capacity and contact responsibilities in the earlier workshop questions. These are reasons to keep checking the transcript directly.</p></section>'

    body+='<section class="section" id="questions"><h2>Inspect the questions in context</h2><p>The default view contains 23 retained wordings. Use the filters to inspect excluded examples or nine earlier comparison questions. Each card shows its meeting context, proposed time, checked answer and the model’s original answers.</p><div class="qe-filters"><label>Review <select id="status-filter"><option value="retain">Retained questions</option><option value="all">All records</option><option value="reject">Excluded examples</option><option value="legacy">Earlier pilot comparison</option></select></label><label>Source <select id="dataset-filter"><option value="all">All conversations</option><option value="ami">AMI</option><option value="earnings">Earnings calls</option></select></label><label>Question writer <select id="origin-filter"><option value="all">All writers</option><option value="authored">Report assistant</option><option value="local">Local 30B model</option><option value="legacy">Earlier pilot</option></select></label><output id="question-count" aria-live="polite"></output></div><div class="qe-questions">'
    body+=''.join(question_card(q,explanations,timing['durations']) for q in questions)+'</div></section>'

    body+='<section class="section" id="harder-questions"><h2>Research review: how should the next questions be harder?</h2><p><strong>The current set does not establish multi-hop reasoning.</strong> Each of its 15 distinct information needs can be answered from one local passage or short exchange. Several transcript excerpts may just be parts of one sentence. A reference answer may also add context that the question did not require. Neither creates another necessary reasoning step.</p><p>The useful next target is a short question whose answer requires connecting separate evidence. One passage might identify who took a task; another supplies what that person promised. Or a later constraint may need to be applied to an earlier plan. The question can stay brief while the evidence needed to answer becomes more demanding.</p><p><a href="https://arxiv.org/html/2407.15754v1#A5">LongVideoBench’s annotation guide</a> is close to the clothing-description example: it includes references to a person in red and to when that person first appeared. Its pattern is to locate the referred person or event, then answer about it. This does not conclusively identify the remembered paper, and some such descriptions can still be resolved from one scene. For meeting audio, an earlier task or proposal can identify a person without an arbitrary visual description.</p>'
    paper_order=['longvideo2024','musique2022','cqg2022','min2019','mulqg2020','reinforced2020','rewrite2024','dpkg2025'];papers={r['id']:r for r in reasoning['papers']}
    body+=table(5,'Eight primary papers reviewed before proposing the next experiment. The method describes the paper; the final column is our proposed use, not a result obtained on these meetings.',['Paper','What it does','What we can take from it'],[[papers[k]['title']+f" ({papers[k]['year']})",papers[k]['method'],papers[k]['relevance']] for k in paper_order])
    body+='<details><summary>Paper links and limits of applying each method here</summary><ol class="qe-reading">'+''.join('<li><a href="'+e(papers[k]['url'])+'">'+e(papers[k]['title'])+'</a> — '+e(papers[k]['authors'])+', '+str(papers[k]['year'])+'. '+e(papers[k]['limit'])+'</li>' for k in paper_order)+'</ol></details>'
    body+='<h3>An existing question that is closer to the target</h3><p>The earlier workshop pilot already contains this question: “Assistant, how did adding a poster session change the number of talks we thought we could fit?” At 09:37.81, A says the maximum is 36 talks. At 13:07.19, A says the plan could have 30 talks, followed by a morning or afternoon of posters. Answering the change requires relating the two planning statements, rather than only finding the later number. These are possible capacities, not confirmed bookings.</p><p>This is a useful example for designing the next review. We should still check the whole earlier discussion for another passage that supplies both facts before treating it as a validated two-step item. <a href="#legacy-authored-W2-1">Inspect the unchanged question and its source passages</a>.</p>'
    body+='<h3>Proposed direction for discussion</h3><p>I recommend beginning with a small set of <strong>two-step questions</strong>. MuSiQue provides the key principle: the second step must depend on the first. CQG and question-rewriting work offer ways to preserve that connection during generation. Min and colleagues show why the final question and supplied evidence must still be checked for shortcuts.</p><ol><li><strong>Identify a participant through an earlier task, then recover a separate commitment.</strong> Use the task description only when it fits how the requester would naturally refer to that person.</li><li><strong>Apply a changed requirement to an earlier plan.</strong> Ask about the consequence for the decision currently being discussed. Exclude cases where a later recap already gives the whole answer.</li><li><strong>Later, connect call history to a document lookup.</strong> Earlier speech should identify the relevant metric or store group; an available document supplies the missing comparison or exact value.</li></ol><p>Before keeping a question, check that two separate facts are necessary, search the whole available discussion for a shortcut, and withhold each required fact while accounting for repeated mentions. A plausible alternative person or metric should test whether identifying the right one matters. Wording, requester motivation and ambiguity need their own review. The same reader model’s agreement cannot certify these properties.</p><p>A later pilot should include early, middle and late question times where the needed evidence has actually become available. Question position, age of the evidence and number of required reasoning steps should be reported separately.</p><p class="callout"><strong>Discussion only:</strong> no new questions, model runs, training or audio injection have been started for this proposal. <a href="../research/question-expansion/reasoning-review.md">Read the full research note</a> · <a href="../research/question-expansion/difficulty-review.json">Inspect the current-set difficulty review</a>.</p></section>'

    body+='<section class="section" id="documents"><h2>What is available for a later document-tool experiment?</h2><p>ConEC pairs earnings calls with presentation slides and earnings releases. A local search program and a page-opening function were tested on the two examples below. Their queries and page choices were supplied by the report assistant; a model did not decide to call the tools.</p>'
    body+=table(6,'Two completed document-search checks from the previous study. These are separate from the 23 retained transcript questions.',['Example request','Source page','Result checked on the page'],[[r['question'],r['source_label'],r['expected']] for r in tools])
    body+='<p>Both calls announce that the documents are on the company website before the proposed question time. The program rejects a lookup before that announcement and a page from the wrong call. This establishes usable source pages and basic access rules, not an assistant’s ability to decide when retrieval is needed.</p></section>'

    body+='<section class="section" id="appendix"><h2>Technical details and earlier diagnostic attempts</h2><details><summary>Transcript timing, model settings and what the reader saw</summary><p>AMI provides manually annotated words and speaker identities. We assumed an extra 0.5 seconds before making a completed excerpt available. EN2002b has no formal participant roles; its requester perspectives come from earlier speech. The other AMI meetings have assigned product-design roles.</p>'
    body+=p(f"For the two earnings calls, ConEC provides corrected words and automatic timing. {study['earnings_untimed_words']:,} of {study['earnings_words']:,} words lack complete start/end boundaries. Words without a final boundary are held until a later timed word provides an anchor. A final excerpt with no later anchor is withheld. This is a text-release convention; earnings audio insertion has not been verified.")
    body+='<p>Generation and reading use Qwen3-30B-A3B-Instruct-2507 through vLLM: BF16 weights, prefix caching, CUDA graphs, a 49,152-token context and an 8 GiB attention cache. Reader responses allow 1,536 output tokens; the largest checked input is 30,452 tokens. Full participant rosters and words harvested from later speech are not reader inputs.</p><p>Removing selected source excerpts can leave equivalent information elsewhere. Removing speaker labels can leave naturally spoken names. These controls must be interpreted alongside source inspection.</p></details>'
    body+='<details><summary>Why the later quotation-copying reader test was not adopted</summary><p>After factual errors, a later instruction asked the reader to copy short supporting quotations before answering. One diagnostic run was cancelled because generation repeatedly produced whitespace instead of completing the record. It saved 29 partial/complete calls, nine reaching the output limit. A retry restricted whitespace and first tested four questions.</p>'
    body+=table(7,'The four-question prerequisite test. Three answers supplied no supporting quotation; the fourth changed capitalisation. The larger follow-up did not run.',['Existing question','Observed result','Decision'],[[r[0],'Declined to answer although the needed fact was present' if i<3 else 'Recovered the growth range but changed the case of a word in the quotation','Did not qualify'] for i,r in enumerate(study['span_rows'])])
    body+='<p>A separate CPU check covers all 41 records with an empty-context rule: when no transcript is supplied, return that context is missing without asking the model to invent an answer. This is a program check, not a model accuracy score. A copied quotation also cannot establish that the conclusion drawn from it is correct.</p></details>'
    body+='<details><summary>Resources used in the previous generation study</summary><p>This report revision and literature review use <strong>0 GPUs</strong>. The five earlier jobs ran one after another, with no overlapping experiment allocation. Each used one H100 SXM with 80 GB VRAM; text-model weights and the attention cache shared GPU 0. No speech or recognition service ran alongside them.</p>'
    body+=table(8,'Historical allocations for existing question and reader outputs. No job was rerun for this revision.',['Job','Purpose','GPU count / type / VRAM','GPU role','Allocation'],study['job_rows'])+p('Those earlier jobs total '+str(study['gpu_hours'])+' GPU hours, with at most one GPU active. The cancelled diagnostic is included.')+'</details>'
    body+='<details><summary>Earlier earnings-dataset survey</summary>'+table(9,'Previously reviewed datasets and their limits. This concerns data selection; the multi-hop question papers are reviewed in Table 5.',['Resource','Possible use','Limit'],[[r['title'],r['relevance'],r['limit']] for r in datasets['papers']])+'<ul>'+''.join('<li><a href="'+e(r['url'])+'">'+e(r['title'])+'</a></li>' for r in datasets['papers'])+'</ul></details></section>'
    body+='<footer class="section"><h2>Data and source records</h2><p><a href="../research/question-expansion/questions.json">Original question and reader records</a> · <a href="../research/question-expansion/timing-statistics.json">Timing data and duration sources</a> · <a href="../research/question-expansion/initial-review.json">Original generation-review records</a> · <a href="../research/question-expansion/reasoning-literature.json">New research-review data</a> · <a href="../research/question-expansion/manifest.json">Public file hashes</a></p><p>Sources: <a href="https://groups.inf.ed.ac.uk/ami/corpus/">AMI Meeting Corpus</a>, <a href="https://github.com/huangruizhe/ConEC">ConEC</a> and <a href="https://github.com/revdotcom/speech-datasets">Rev speech datasets</a>. These assistant requests are synthetic. The original participants did not record them.</p></footer></div></main>'

    css='''.qe-metrics{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:12px;margin:22px 0}.qe-metrics>div{border:1px solid var(--border);border-radius:9px;padding:14px}.qe-metrics dt{color:var(--muted);font-size:.9rem}.qe-metrics dd{font-size:1.7rem;font-weight:650;margin:5px 0 0}.qe-table{overflow:auto;border:1px solid var(--border);border-radius:10px;margin:22px 0}.qe-table table{min-width:700px;table-layout:auto}.qe-table th,.qe-table td{vertical-align:top}.qe-stages{display:grid;gap:14px;grid-template-columns:repeat(auto-fit,minmax(245px,1fr))}.qe-stages>div{border:1px solid var(--border);border-radius:10px;padding:16px;background:var(--surface-2)}.qe-stages h3{font-size:1rem;margin-top:0}.qe-stages dt{font-weight:650;margin-top:12px}.qe-stages dd{margin:4px 0 0}.qe-flow{margin:24px 0}.qe-plots{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px}.qe-plots img{display:block;width:100%;height:auto;background:white;border:1px solid var(--border);border-radius:8px}.qe-plots>div>p{margin:7px 0}.qe-chart-control{display:flex;gap:12px;flex-wrap:wrap;align-items:center}.qe-time{color:var(--accent);font-weight:600}.qe-questions{display:grid;gap:22px}.qe-question h3{font-size:1.2rem}.qe-question p,.qe-question li{overflow-wrap:anywhere}.qe-tags,.qe-filters{display:flex;gap:10px;flex-wrap:wrap;align-items:center}.qe-filters{margin:22px 0}.qe-filters label{display:flex;gap:8px;align-items:center}.qe-filters select,.qe-chart-control select{background:var(--surface);color:var(--text);border:1px solid var(--border);border-radius:6px;padding:8px;max-width:100%}.qe-reader{margin:14px 0;background:var(--surface-2);padding:14px;border-radius:8px}.qe-reader h4{margin:0 0 9px;font-size:1rem}.qe-reader p{margin:7px 0}.qe-reading li{margin-bottom:14px}figcaption{margin-top:12px;color:var(--muted)}details{margin:19px 0}summary{cursor:pointer;color:var(--accent);font-weight:600}details>p:first-of-type{margin-top:15px}[hidden]{display:none!important}@media(max-width:700px){.qe-plots{grid-template-columns:1fr}.qe-stages{grid-template-columns:1fr}.qe-filters label{width:100%;justify-content:space-between}}'''
    css+='''#timing-figure{margin:24px 0}.qe-table{overflow:visible}.qe-table-scroll{overflow:auto}.qe-table-caption{padding:14px 16px;margin:0;font-size:.9rem;color:var(--muted);border-bottom:1px solid var(--border)}.qe-table th{overflow-wrap:normal;word-break:normal;hyphens:none}.qe-sr-only{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}section[id],article[id]{scroll-margin-top:120px}'''
    chart_data={k:v['summary'] for k,v in timing['cohorts'].items()}
    js="""const fields=['status','dataset','origin'];function filter(){let n=0;for(const c of document.querySelectorAll('.qe-question')){c.hidden=!fields.every(f=>{const v=document.getElementById(f+'-filter').value;return v==='all'||c.dataset[f]===v});if(!c.hidden)n++}document.getElementById('question-count').textContent=n+' questions shown'}for(const f of fields)document.getElementById(f+'-filter').addEventListener('change',filter);filter();function reveal(){const c=document.getElementById(location.hash.slice(1));if(c?.classList.contains('qe-question')){for(const f of fields)document.getElementById(f+'-filter').value='all';filter();c.scrollIntoView()}}addEventListener('hashchange',reveal);if(location.hash)reveal();"""
    js+='const timingData='+json.dumps(chart_data)+';'
    js+="""function timingPlot(){const cohort=document.getElementById('timing-cohort').value,s=timingData[cohort],label=cohort==='wordings'?'retained wordings':'distinct questions';document.getElementById('timing-summary').textContent='Counting '+s.n+' '+label+': mean '+s.mean_elapsed_minutes.toFixed(1)+' minutes after the start, or '+s.mean_percent.toFixed(1)+'% of the conversation.';for(const measure of ['percent','minutes']){const stem='../research/question-expansion/figures/'+cohort+'-'+measure;document.getElementById('timing-'+measure).src=stem+'.png';for(const ext of ['svg','pdf'])document.getElementById(measure+'-'+ext).href=stem+'.'+ext}}document.getElementById('timing-cohort').addEventListener('change',timingPlot);timingPlot();"""
    version=hashlib.sha256((ROOT/'assets/site.css').read_bytes()).hexdigest()[:12]
